  public static final PhonAdapter<VoxResult<TerminalInputResult, TerminalError>> ADAPTER = new PhonAdapter<>() {
    @Override public SchemaClosure schema() { return SCHEMA; }
    @Override public void encode(PhonEncoder encoder, VoxResult<TerminalInputResult, TerminalError> value) throws PhonException {
      if (value.isSuccess()) {
        encoder.writeU32Unaligned(0);
        encoder.writeAdapted(TerminalInputResult.ADAPTER, value.success());
        return;
      }
      encoder.writeU32Unaligned(1);
      switch (value.kind()) {
        case APPLICATION_ERROR:
          encoder.writeU32Unaligned(0);
          encoder.writeAdapted(TerminalError.ADAPTER, value.applicationError());
          return;
        case UNKNOWN_METHOD: encoder.writeU32Unaligned(1); return;
case INVALID_PAYLOAD: encoder.writeU32Unaligned(2); encoder.writeString(value.detail()); return;
case CANCELLED: encoder.writeU32Unaligned(3); return;
case CONNECTION_CLOSED: encoder.writeU32Unaligned(4); return;
case CONNECTION_SHUTDOWN: encoder.writeU32Unaligned(5); return;
case SEND_FAILED: encoder.writeU32Unaligned(6); return;
case TIMED_OUT: encoder.writeU32Unaligned(7); return;
case INDETERMINATE: encoder.writeU32Unaligned(8); return;
default: throw new PhonException(PhonException.Kind.ENCODE, "invalid response result kind");
}
    }
    @Override public VoxResult<TerminalInputResult, TerminalError> decode(PhonDecoder decoder) throws PhonException {
      long outer = decoder.readU32Unaligned();
      if (outer == 0) return VoxResult.success(decoder.readAdapted(TerminalInputResult.ADAPTER));
      if (outer != 1) throw new PhonException(PhonException.Kind.MALFORMED, "invalid Result discriminant");
      long error = decoder.readU32Unaligned();
      switch ((int) error) {
        case 0: return VoxResult.applicationError(decoder.readAdapted(TerminalError.ADAPTER));
        case 1: return VoxResult.infrastructure(VoxResult.Kind.UNKNOWN_METHOD);
case 2: return VoxResult.infrastructure(VoxResult.Kind.INVALID_PAYLOAD, decoder.readString());
case 3: return VoxResult.infrastructure(VoxResult.Kind.CANCELLED);
case 4: return VoxResult.infrastructure(VoxResult.Kind.CONNECTION_CLOSED);
case 5: return VoxResult.infrastructure(VoxResult.Kind.CONNECTION_SHUTDOWN);
case 6: return VoxResult.infrastructure(VoxResult.Kind.SEND_FAILED);
case 7: return VoxResult.infrastructure(VoxResult.Kind.TIMED_OUT);
case 8: return VoxResult.infrastructure(VoxResult.Kind.INDETERMINATE);
default: throw new PhonException(PhonException.Kind.MALFORMED, "invalid VoxError discriminant");
}
    }
  };
